// Where Moltys come from. The console only ever talks to a CreatureCatalog, so the
// bundled LocalCatalog can be swapped for a CloudCatalog (or a merge of both)
// without touching the pages.
//
// A .molty file is opaque to the console: it is read as bytes and POSTed verbatim to
// the device (POST /api/creature/file). Its format is owned by the firmware's loader
// (creatures/MOLTY-FORMAT.md). The bundled set is the 29 cute-kit Moltys:
// catalog.json + thumbs/ are generated by tools/thumbs.mjs, the .molty bytes by
// creatures/tools/molty-export.mjs — all inlined, so it works offline.

import bundled from './catalog.json';

export interface CreatureEntry {
  id: string;            // stable id (cute-kit id, e.g. "cute-duck"), also sent as ?name= on upload
  name: string;
  blurb?: string;
  author?: string;
  /** Image URL (bundled thumbnails are data: URLs). */
  thumb?: string;
  /** Where the .molty bytes live: file name of a bundled .molty, or an absolute/relative URL. */
  file?: string;
  inline?: string;
}

export interface CreatureCatalog {
  readonly label: string;
  list(): Promise<CreatureEntry[]>;
  /** The raw .molty bytes for one entry. */
  fetchFile(entry: CreatureEntry): Promise<Uint8Array>;
}

const enc = new TextEncoder();

const FILES: Record<string, string> = Object.fromEntries(
  Object.entries(import.meta.glob<string>('@molty/*.molty', { eager: true, import: 'default' }))
    .map(([p, b64]) => [p.split('/').pop()!, b64]));
const THUMBS: Record<string, string> = Object.fromEntries(
  Object.entries(import.meta.glob<string>('./thumbs/*.webp', { eager: true, import: 'default' }))
    .map(([p, url]) => [p.split('/').pop()!.replace(/\.webp$/, ''), url]));

export const b64bytes = (b64: string) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

async function fetchBytes(url: string): Promise<Uint8Array> {
  const res = await fetch(url, { cache: 'no-store' });
  if (!res.ok) throw new Error(`fetch ${url}: ${res.status}`);
  return new Uint8Array(await res.arrayBuffer());
}

/** Catalog bundled into the console (src/catalog/catalog.json). Works offline. */
export class LocalCatalog implements CreatureCatalog {
  readonly label = 'bundled';
  private entries: CreatureEntry[];
  constructor(entries: CreatureEntry[] = (bundled as { creatures: CreatureEntry[] }).creatures) {
    this.entries = entries.map((e) => ({ ...e, thumb: e.thumb ?? THUMBS[e.id] }));
  }
  async list() { return this.entries; }
  async fetchFile(e: CreatureEntry) {
    if (e.inline !== undefined) return enc.encode(e.inline);
    if (e.file && FILES[e.file]) return b64bytes(FILES[e.file]);
    if (e.file) return fetchBytes(e.file);
    throw new Error(`${e.id} has no file`);
  }
}

/**
 * Remote catalog: GET <url> → {creatures: CreatureEntry[]}; relative `file` paths
 * resolve against <url>. Stub: no hosted catalog exists yet.
 */
export class CloudCatalog implements CreatureCatalog {
  readonly label: string;
  constructor(private url: string) { this.label = new URL(url, location.href).host; }
  async list() {
    const res = await fetch(this.url, { cache: 'no-store' });
    if (!res.ok) throw new Error(`catalog ${res.status}`);
    const body = (await res.json()) as { creatures?: CreatureEntry[] };
    return (body.creatures ?? []).map((e) => ({ ...e, file: e.file && new URL(e.file, this.url).href, thumb: e.thumb && new URL(e.thumb, this.url).href }));
  }
  async fetchFile(e: CreatureEntry) {
    if (e.inline !== undefined) return enc.encode(e.inline);
    if (!e.file) throw new Error(`${e.id} has no file`);
    return fetchBytes(e.file);
  }
}

/** ?catalog=<url> selects a cloud catalog; default is the bundled one. */
export function defaultCatalog(): CreatureCatalog {
  const url = new URLSearchParams(location.search).get('catalog');
  return url ? new CloudCatalog(url) : new LocalCatalog();
}
